-- Owner-private planning only; all fictional fixtures are rolled back by the harness.
RESET ROLE;
INSERT INTO firstten_policy_test.ids(label,id) VALUES('teacher_project_a','f5000000-0000-4000-8000-000000000101'),('teacher_project_a2','f5000000-0000-4000-8000-000000000102'),('teacher_project_b','f5000000-0000-4000-8000-000000000103');
INSERT INTO public.projects(id,user_id,name,stage) VALUES(firstten_policy_test.id('teacher_project_a'),firstten_policy_test.id('owner_a'),'Fictional lesson planning',1),(firstten_policy_test.id('teacher_project_a2'),firstten_policy_test.id('owner_a'),'Fictional second planning project',1),(firstten_policy_test.id('teacher_project_b'),firstten_policy_test.id('owner_b'),'Fictional other owner planning',1);
CREATE FUNCTION firstten_policy_test.empty_teacher_plan() RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $fn$ SELECT $doc${"schemaVersion": 1, "className": "", "audience": "", "learningObjectives": [], "assignment": "", "sessionMinutes": 60, "plannedLearners": null, "scheduledOn": null, "assessment": "", "facilitatorNotes": ""}$doc$::jsonb $fn$;
CREATE FUNCTION firstten_policy_test.teacher_document() RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT document FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a') $$;
CREATE FUNCTION firstten_policy_test.teacher_save(doc jsonb) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),coalesce((SELECT revision FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0),gen_random_uuid(),doc) $$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.empty_teacher_plan(),firstten_policy_test.teacher_document(),firstten_policy_test.teacher_save(jsonb) TO authenticated,anon;
CREATE TABLE firstten_policy_test.teacher_ack(label text PRIMARY KEY,result jsonb);
GRANT SELECT,INSERT ON firstten_policy_test.teacher_ack TO authenticated;
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.teacher_plans'::regclass),'teacher planning table has RLS');
SELECT ok((SELECT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] FROM pg_proc WHERE oid='public.save_teacher_plan(uuid,bigint,uuid,jsonb)'::regprocedure),'teacher save uses fixed search path and narrow definer');
SELECT ok(NOT has_table_privilege('authenticated','public.teacher_plans','INSERT,UPDATE,DELETE'),'browser roles have no direct planning DML');
SELECT ok(NOT has_function_privilege('anon','public.save_teacher_plan(uuid,bigint,uuid,jsonb)','EXECUTE'),'anonymous cannot invoke teacher save');
SELECT ok(NOT has_table_privilege('service_role','public.teacher_plans','SELECT,INSERT,UPDATE,DELETE'),'service role has no planning shortcut');
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
INSERT INTO firstten_policy_test.teacher_ack SELECT 'created',public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),0,'f5000000-0000-4000-8000-000000000201',jsonb_set(jsonb_set(firstten_policy_test.empty_teacher_plan(),'{schemaVersion}','1.0'),'{sessionMinutes}','60.0'));
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.teacher_ack WHERE label='created'),'true','ordinary stage-1 owner can create a private lesson plan');
SELECT is((SELECT revision FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),1::bigint,'lesson plan starts at revision one');
SELECT is(firstten_policy_test.teacher_document()->'plannedLearners','null'::jsonb,'unknown planned capacity remains null');
SELECT is(firstten_policy_test.teacher_document()->>'sessionMinutes','60','integer values are normalized before hashing');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),0,'f5000000-0000-4000-8000-000000000201',firstten_policy_test.empty_teacher_plan()),(SELECT result FROM firstten_policy_test.teacher_ack WHERE label='created'),'equivalent integer retry returns the same acknowledgement');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),0,'f5000000-0000-4000-8000-000000000201',jsonb_set(firstten_policy_test.empty_teacher_plan(),'{className}','"Changed"'))->>'code','IDEMPOTENCY_CONFLICT','retry token cannot carry changed content');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),0,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','CONFLICT','create cannot overwrite a lesson plan');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.teacher_plans SET revision=10$case$),'error:42501','owner cannot directly tamper with lesson revision');
SELECT is(firstten_policy_test.attempt($case$DELETE FROM public.teacher_plans$case$),'error:42501','owner cannot bypass explicit planning operations');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.teacher_plans(project_id,document,last_mutation_id,last_mutation_hash) VALUES(firstten_policy_test.id('teacher_project_a2'),firstten_policy_test.empty_teacher_plan(),gen_random_uuid(),repeat('a',64))$case$),'error:42501','direct planning insert denied');
RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_b');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'owner_b cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','owner_b cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('editor');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'editor cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','editor cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('viewer');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'viewer cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','viewer cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('student');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'student cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','student cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('teacher');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'teacher cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','teacher cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('unrelated');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'unrelated cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','unrelated cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('admin');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'admin cannot read another owner lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','NOT_FOUND','admin cannot save a forged project lesson');
RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_b');
SET LOCAL ROLE authenticated;
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_b'),0,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'ok','true','second owner creates independently');
SELECT is((SELECT count(*) FROM public.teacher_plans),1::bigint,'second owner sees only own lesson');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT is(firstten_policy_test.attempt($case$SELECT * FROM public.teacher_plans$case$),'error:42501','anonymous lesson reads denied');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true),set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.save_teacher_plan('f5000000-0000-4000-8000-000000000999',0,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','UNAUTHENTICATED','teacher save requires actual authenticated subject');
RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
CREATE TEMP TABLE teacher_preserved AS SELECT revision,document FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{schemaVersion}','2'))->>'code','INVALID_PLAN','reject schema version');
SELECT is(firstten_policy_test.teacher_save(firstten_policy_test.teacher_document()||'{"studentRecords":[]}')->>'code','INVALID_PLAN','reject unknown student field');
SELECT is(firstten_policy_test.teacher_save(firstten_policy_test.teacher_document()-'assignment')->>'code','INVALID_PLAN','reject missing required key');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{className}',to_jsonb(repeat('x',121))))->>'code','INVALID_PLAN','reject long class name');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{facilitatorNotes}',to_jsonb(repeat('x',4001))))->>'code','INVALID_PLAN','reject long notes');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{scheduledOn}','"2026-02-30"'))->>'code','INVALID_PLAN','reject invalid day');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{plannedLearners}','2.5'))->>'code','INVALID_PLAN','reject fractional capacity');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{plannedLearners}','-1'))->>'code','INVALID_PLAN','reject negative capacity');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{plannedLearners}','10001'))->>'code','INVALID_PLAN','reject excess capacity');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{sessionMinutes}','0'))->>'code','INVALID_PLAN','reject zero duration');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{sessionMinutes}','481'))->>'code','INVALID_PLAN','reject excess duration');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{learningObjectives}',(SELECT jsonb_agg('goal'::text) FROM generate_series(1,9))))->>'code','INVALID_PLAN','reject excess objectives');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(firstten_policy_test.teacher_document(),'{assignment}',to_jsonb(repeat('x',65537))))->>'code','INVALID_PLAN','reject oversize payload');
SELECT is((SELECT to_jsonb(t) FROM (SELECT revision,document FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a'))t),(SELECT to_jsonb(t) FROM teacher_preserved t),'invalid lesson saves preserve acknowledged content and revision');
SELECT is(firstten_policy_test.teacher_save(jsonb_set(jsonb_set(firstten_policy_test.teacher_document(),'{className}','"  Customer discovery lab  "'),'{plannedLearners}','45'))->>'ok','true','owner explicitly saves an editable lesson and planned capacity');
SELECT is(firstten_policy_test.teacher_document()->>'className','Customer discovery lab','lesson text is normalized without truncation');
SELECT is((SELECT revision FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),2::bigint,'successful update increments exactly once');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),1,gen_random_uuid(),firstten_policy_test.empty_teacher_plan())->>'code','CONFLICT','stale write cannot overwrite the updated lesson');
SELECT is(public.save_teacher_plan(firstten_policy_test.id('teacher_project_a'),0,'f5000000-0000-4000-8000-000000000201',firstten_policy_test.empty_teacher_plan())->>'code','CONFLICT','old retry after later lesson save cannot replay old content');
RESET ROLE;
SELECT is(firstten_policy_test.attempt($case$UPDATE public.teacher_plans SET user_id=firstten_policy_test.id('owner_b') WHERE project_id=firstten_policy_test.id('teacher_project_a')$case$),'error:42501','privileged path cannot silently transfer lesson owner');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.teacher_plans SET project_id=firstten_policy_test.id('teacher_project_a2') WHERE project_id=firstten_policy_test.id('teacher_project_a')$case$),'error:23514','lesson cannot move between projects even with same owner');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.teacher_plans SET id=gen_random_uuid() WHERE project_id=firstten_policy_test.id('teacher_project_a')$case$),'error:23514','lesson identity immutable');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.teacher_plans SET created_at=created_at+interval '1 second' WHERE project_id=firstten_policy_test.id('teacher_project_a')$case$),'error:23514','lesson created timestamp immutable');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.teacher_plans(user_id,project_id,document,last_mutation_id,last_mutation_hash) VALUES(firstten_policy_test.id('owner_b'),firstten_policy_test.id('teacher_project_a2'),firstten_policy_test.empty_teacher_plan(),gen_random_uuid(),repeat('a',64))$case$),'error:23503','composite foreign key independently rejects wrong owner/project');
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
DELETE FROM public.projects WHERE id=firstten_policy_test.id('teacher_project_a');
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_a')),0::bigint,'explicit project deletion cascades its private lesson');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.teacher_plans WHERE project_id=firstten_policy_test.id('teacher_project_b')),1::bigint,'another owner lesson survives cascade');
